(** * The IVXV campaign group *)

(** The 2048-bit safe-prime group used in the IVXV (Estonian internet
voting) benchmark campaign: the group of [bench/ivxv-diff/group.txt],
produced by Verificatum's [vog -gen ModPGroup -fixed 2048]. Here
[p = 2q + 1] with [q] of 2047 bits, and the group is the order-[q]
subgroup of [Z_p^*] ([Utility/Zpstar.v]) with the generator [g] of the
group description.

The primality of [p] and [q] is ASSUMED, not certified: [prime_q] and
[prime_p] are axioms, and therefore show up in [Print Assumptions] of
everything built on this file. The relation [p = k·q + 1] (with
[k = p / q = 2]) and the order of [g] are checked by computation.

The file is generated by [bench/ivxv-diff/mkins.py] from the group part of
[HeliosTallyIns.v] and should not be edited by hand. It is used by
[VerificatumIvxvIns.v] and extracted to OCaml by [src/Extraction/Ivxvlib]. *)
From Stdlib Require Import Utf8 ZArith Znumtheory Zpow_facts.
From Utility Require Import Zpstar Util.
From Examples Require Import BigNPow.
Import Vspace Schnorr Zpfield Zpgroup.

Section IvxvGroup.

  (** The 2047-bit subgroup order [q]. *)
  Definition q : Z := %Z.
  (** The 2048-bit safe prime [p = 2q + 1]. *)
  Definition p : Z := %Z.

  (** ASSUMED: [q] and [p] are prime. These are axioms, not certificates. *)
  Axiom prime_q : Znumtheory.prime q.
  Axiom prime_p : Znumtheory.prime p.

  (** The cofactor [k = p / q], equal to 2. *)
  Definition k : Z := Z.div p q.
  (** [p = k·q + 1], checked by computation; it is the shape required by the
      [Zpstar] group operations. *)
  Theorem safe_prime : p = (k * q + 1)%Z.
  Proof. vm_cast_no_check (eq_refl p). Qed.

  (** The generator of the group description, as an integer. *)
  Definition gval : Z := %Z.
  (** [gval^q mod p = 1], so [gval] lies in the subgroup of order [q]. The
      power is computed with the [BigN] implementation of [BigNPow], proved
      equal to [Zpow_mod]. *)
  Theorem g_order : Zpow_mod gval q p = 1%Z.
  Proof.
    unfold q; rewrite BigNPow.bpow_mod_spec by (vm_compute; discriminate).
    vm_cast_no_check (eq_refl 1%Z).
  Qed.
  (** The generator as a group element, with the membership proof [g_order]. *)
  Definition g : @Schnorr_group p q.
  Proof.
    refine {| Schnorr.v := gval; Ha := conj eq_refl eq_refl : (0 < gval < p)%Z; Hb := g_order |}.
  Defined.

End IvxvGroup.
